-- =====================================================================
-- Public EU lists for the AI formulator (owner, Oct 2026), generated by
-- web/scripts/eu-lists.mjs from the Food and Feed Information Portal:
-- the EU Register of health claims (Reg. 1924/2006) and the EU Novel Food
-- status Catalogue. There are no harmonised EU maximum doses to load.
-- Reference data for Admin and Sales; Production does not need it.
-- =====================================================================

create table public.eu_health_claims (
  code          text primary key,
  substance     text not null,
  claim         text not null,
  conditions    text,
  restrictions  text,
  status        text not null check (status in ('authorised', 'non_authorised', 'revoked')),
  claim_type    text
);
create index eu_health_claims_status_idx on public.eu_health_claims (status);

create table public.eu_novel_food_status (
  code          text primary key,
  name          text not null,
  synonyms      text,
  common_names  text,
  parts         jsonb not null,    -- [{part, status}], the Catalogue's status per part of the source
  description   text
);

create table public.eu_lists_info (downloaded_on date not null);

alter table public.eu_health_claims enable row level security;
alter table public.eu_novel_food_status enable row level security;
alter table public.eu_lists_info enable row level security;
create policy eu_health_claims_select on public.eu_health_claims for select to authenticated using (public.has_role('admin', 'sales'));
create policy eu_novel_food_status_select on public.eu_novel_food_status for select to authenticated using (public.has_role('admin', 'sales'));
create policy eu_lists_info_select on public.eu_lists_info for select to authenticated using (public.has_role('admin', 'sales'));

on conflict (code) do update set substance = excluded.substance, claim = excluded.claim, conditions = excluded.conditions,
  restrictions = excluded.restrictions, status = excluded.status, claim_type = excluded.claim_type;

on conflict (code) do update set name = excluded.name, synonyms = excluded.synonyms, common_names = excluded.common_names,
  parts = excluded.parts, description = excluded.description;

update public.eu_lists_info set downloaded_on = date '2026-10-31';
