insert into public.eu_health_claims (code, substance, claim, conditions, restrictions, status, claim_type) values
('POL-HC-11221', 'Isomaltulose', 'Isomaltulose contributes to normal energy- yielding metabolism', null, null, 'non_authorised', '13(5)'),
('POL-HC-6421', 'Monascus purpureous (red yeast rice)', 'Monacolin K from red yeast rice contributes to the maintenance of normal blood cholesterol levels Following the amendment of Annex III of Regulation (EC) 1925/2006 as regards monacolins from red yeast rice, by which monacolins have been placed in Part B of Annex III, under ‘Restricted substances’, the use of monacolins from red yeast rice at levels of 3mg and more per portion of the product recommended for daily consumption is prohibited. Consequently, the health claim on monacolin K from red yeast rice related to the contribution to the maintenance of normal blood cholesterol levels, under the daily intake of 10 mg of monacolin K from red yeast rice (Entry ID: 1648, 1700), has been revoked from the Union list of permitted health claims with Commission Regulation (EU) 2024/2041.', 'The claim may be used only for food which provides a daily intake of 10 mg of monacolin K from red yeast rice. In order to bear the claim, information shall be given to the consumer that the beneficial effect is obtained with a daily intake of 10 mg of monacolin K from fermented red yeast rice preparations.', null, 'revoked', '13(1)'),
('POL-HC-6381', 'Glucomannan (konjac mannan)', 'Glucomannan in the context of an energy restricted diet contributes to weight loss', 'The claim may be used only for food which contains 1 g of glucomannan per quantified portion. In order to bear the claim information shall be given to the consumer that the beneficial effect is obtained with a daily intake of 3 g of glucomannan in three doses of 1 g each, together with 1-2 glasses of water, before meals and in the context of an energy-restricted diet.', 'Warning of choking to be given for people with swallowing difficulties or when ingesting with inadequate fluid intake - advice on taking with plenty of water to ensure substance reaches stomach.', 'authorised', '13(1)'),
('POL-HC-6382', 'Guar Gum', 'Guar gum contributes to the maintenance of normal blood cholesterol levels', 'The claim may be used only for food which provides a daily intake of 10 g of guar gum. In order to bear the claim, information shall be given to the consumer that the beneficial effect is obtained with a daily intake of 10 g of guar gum.', 'Warning of choking to be given for people with swallowing difficulties or when ingesting with inadequate fluid intake - advice on taking with plenty of water to ensure substance reaches stomach.', 'authorised', '13(1)'),
('POL-HC-6383', 'Hydroxypropyl methylcellulose (HPMC)', 'Consumption of Hydroxypropyl methylcellulose with a meal contributes to a reduction in the blood glucose rise after that meal', 'The claim may be used only for food which contains 4 g of HPMC per quantified portion as part of the meal. In order to bear the claim information shall be given to the consumer that the beneficial effect is obtained by consuming 4 g of HPMC as part of the meal.', 'Warning of choking to be given for people with swallowing difficulties or when ingesting with inadequate fluid intake - advice on taking with plenty of water to ensure substance reaches stomach.', 'authorised', '13(1)'),
('POL-HC-6210', 'Zinc', 'Prevents bad breath by neutralising of volatile sulphur compounds (VSC) in the mouth and oral cavity.', null, null, 'non_authorised', '13(5)'),
('POL-HC-6211', 'Lactobacillus rhamnosus GG (LGG)', 'Lactobacillus GG helps to maintain defence against intestinal pathogens', null, null, 'non_authorised', '13(5)'),
('POL-HC-6212', 'Collagen hydrolysate, a characteristic collagen peptide mixture', 'Characteristic collagen peptide mixture (collagen hydrolysate) having a beneficial physiological effect on the maintenance of joint health in physically active people', null, null, 'non_authorised', '13(5)'),
('POL-HC-6213', 'Lactobacillus delbrueckii subsp. bulgaricus strain AY/CSL (LMG P-17224) and Streptococcus thermophilus strain 9Y/CSL (LMG P-17225)', 'Maintaining the gut health by normalizing the intestinal flora', null, null, 'non_authorised', '14(1)(b)'),
('POL-HC-6267', '&alpha;-linolenic acid (ALA) & linoleic acid (LA), essential fatty acids', 'Essential fatty acids are needed for normal growth and development of children.', 'Information to the consumer that the beneficial effect is obtained with a daily intake of 2 g of α-linolenic acid (ALA) and a daily intake of 10 g of linoleic acid (LA).', null, 'authorised', '14(1)(b)'),
('POL-HC-6268', 'Calcium and vitamin D', 'Calcium and vitamin D are needed for normal growth and development of bone in children', 'The claim can be used only for food which is at least a source of calcium and vitamin D as referred to in the claim SOURCE OF [NAME OF VITAMIN/S] AND/OR [NAME OF MINERAL/S] as listed in the Annex to Regulation 1924/2006.', null, 'authorised', '14(1)(b)'),
('POL-HC-6269', 'Calcium', 'Calcium is needed for normal growth and development of bone in children.', 'The claim can be used only for food which is at least a source of calcium as referred to in the claim SOURCE OF [NAME OF VITAMIN/S] AND/OR [NAME OF MINERAL/S] as listed in the Annex to Regulation 1924/2006.', null, 'authorised', '14(1)(b)'),
('POL-HC-6325', 'Black tea from Camellia sinensis', 'Black tea helps you to focus attention', null, null, 'non_authorised', '13(5)'),
('POL-HC-6326', 'Activated charcoal', 'Activated charcoal contributes to reducing excessive flatulence after eating', 'The claim may be used only for food which contains 1 g of activated charcoal per quantified portion. In order to bear the claim information shall be given to the consumer that the beneficial effect is obtained with 1 g which should be taken at least 30 minutes before and 1 g shortly after the meal.', null, 'authorised', '13(1)'),
('POL-HC-6327', 'Alpha-linolenic acid (ALA)', 'ALA contributes to the maintenance of normal blood cholesterol levels', 'The claim may be used only for food which is at least a source of ALA as referred to in the claim SOURCE OF OMEGA 3 FATTY ACIDS as listed in the Annex to Regulation (EC) No 1924/2006. Information shall be given to the consumer that the beneficial effect is obtained with a daily intake of 2 g of ALA.', null, 'authorised', '13(1)'),
('POL-HC-6384', 'Hydroxypropyl methylcellulose (HPMC)', 'Hydroxypropyl methylcellulose contributes to the maintenance of normal blood cholesterol levels', 'The claim may be used only for food which provides a daily intake of 5 g of HPMC. In order to bear the claim information shall be given to the consumer that the beneficial effect is obtained with a daily intake of 5 g of HPMC.', 'Warning of choking to be given for people with swallowing difficulties or when ingesting with inadequate fluid intake - advice on taking with plenty of water to ensure substance reaches stomach.', 'authorised', '13(1)'),
('POL-HC-6385', 'Iodine', 'Iodine contributes to normal cognitive function', 'The claim may be used only for food which is at least a source of iodine as referred to in the claim SOURCE OF [NAME OF VITAMIN/S] AND/OR [NAME OF MINERAL/S] as listed in the Annex to Regulation (EC) No 1924/2006.', null, 'authorised', '13(1)'),
('POL-HC-6386', 'Iodine', 'Iodine contributes to normal energy-yielding metabolism', 'The claim may be used only for food which is at least a source of iodine as referred to in the claim SOURCE OF [NAME OF VITAMIN/S] AND/OR [NAME OF MINERAL/S] as listed in the Annex to Regulation (EC) No 1924/2006.', null, 'authorised', '13(1)'),
('POL-HC-6387', 'Iodine', 'Iodine contributes to normal functioning of the nervous system', 'The claim may be used only for food which is at least a source of iodine as referred to in the claim SOURCE OF [NAME OF VITAMIN/S] AND/OR [NAME OF MINERAL/S] as listed in the Annex to Regulation (EC) No 1924/2006.', null, 'authorised', '13(1)'),
('POL-HC-6214', 'L-tyrosine', 'L-tyrosine is essential for the natural formation of dopamine', null, null, 'non_authorised', '13(5)'),
('POL-HC-6215', 'Slowly digestible starch', 'Consumption of products high in slowly digestible starch (SDS) raises blood glucose concentration less after a meal compared to products low in SDS', 'The claim may be used only on food where the digestible carbohydrates provide at least 60 % of the total energy and where at least 55 % of those carbohydrates is digestible starch, of which at least 40 % is SDS', null, 'authorised', '13(5)'),
('POL-HC-6216', 'Beta-palmitate', 'Beta-palmitate enrichment contributes to increase calcium absorption', null, null, 'non_authorised', '14(1)(b)'),
